mapper.sql:
SELECT id, MATCH(search_terms) AGAINST (#{sample.terms}

  IN BOOLEAN MODE
  IN NATURAL LANGUAGE MODE

) AS score
FROM knowledge_chunk WHERE enterprise_id = #{sample.enterprise} AND

  
    
      (document_id = #{version.id} AND file_id = #{version.activeFileId} AND generation =
      #{version.activeGeneration})
    
  
  
    (document_id, file_id, generation) IN
    
      (#{version.id}, #{version.activeFileId}, #{version.activeGeneration})
    
  

AND MATCH(search_terms) AGAINST (#{sample.terms}

  IN BOOLEAN MODE
  IN NATURAL LANGUAGE MODE

) > 0
ORDER BY score DESC LIMIT #{sample.limit}
